<!DOCTYPE html><html lang="en"><?= view('components/head',['pageTitle'=>$pageTitle]) ?><body><?= view('components/header') ?><main class="container-fluid"><div class="row admin-layout"><?= view('components/admin_sidebar') ?><section class="col admin-content"><p class="eyebrow">Fulfillment</p><h1 class="section-title mb-4">Orders</h1><?php if (session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><div class="surface-card p-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th>Jotform</th><th>Total</th><th></th></tr></thead><tbody><?php if ($orders === []): ?><tr><td colspan="7" class="text-center py-5 text-muted-brand">No orders yet.</td></tr><?php endif; ?><?php foreach($orders as $order):?><tr><td>#<?= esc($order['id']) ?></td><td><?= esc($order['display_name'] ?: $order['username']) ?><small class="d-block text-muted-brand"><?= esc($order['email']) ?></small></td><td><?= esc(date('M j, Y', strtotime($order['created_at']))) ?></td><td><span class="badge text-bg-warning"><?= esc(ucfirst($order['status'])) ?></span></td><td><span class="badge <?= $order['jotform_status'] === 'synced' ? 'text-bg-success' : ($order['jotform_status'] === 'failed' ? 'text-bg-danger' : 'text-bg-secondary') ?>"><?= esc(str_replace('_', ' ', ucfirst($order['jotform_status']))) ?></span></td><td>₱<?= number_format($order['total'], 2) ?></td><td class="text-end"><a class="btn btn-outline-brand btn-sm" href="/admin/orders/<?= esc($order['id']) ?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div></div></section></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script></body></html>
